   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="从周围人群的谈话中你大概了解到了这位“毒蛇”究竟是个什么人。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT206_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [68]={next_id=69, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“毒蛇”于八年前首次出现，悄无声息地杀死了某个藏在沙漠中的小部族，只在现场留下了一串蜿蜒如蛇的血迹。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT206_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [69]={next_id=70, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这件事当时被官方定性为沙漠的内部冲突，并未太过在意，但接下来几年中，类似事件屡次发生，严重影响了本地的秩序，这才逼得这里的管理者不得不正视这个人。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT206_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
